<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1" />
  <title>ScreenVault — UI/UX Inspiration Library</title>
  <meta name="description" content="ScreenVault is a massive UI/UX inspiration library with 615,900+ screens, powerful search, and workflow tools for design teams." />
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    :root {
      --bg: #fbfbfd;
      --surface: #ffffff;
      --surface-2: #f4f6fb;
      --text: #12131a;
      --muted: #5f6675;
      --line: #e6e9f2;
      --accent: #4f6bff;
      --accent-2: #7b5cff;
      --radius-lg: 20px;
      --radius-md: 14px;
      --shadow: 0 10px 40px rgba(17, 24, 39, 0.06);
      --ease: cubic-bezier(.22,.61,.36,1);
    }
    * { box-sizing: border-box; }
    html, body { margin: 0; padding: 0; }
    body {
      font-family: Inter, system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
      background: linear-gradient(180deg, #ffffff 0%, var(--bg) 100%);
      color: var(--text);
      line-height: 1.5;
    }
    a { color: inherit; text-decoration: none; }
    .container { width: min(1140px, 92vw); margin: 0 auto; }

    .announcement {
      background: #11131f;
      color: #eef0f7;
      text-align: center;
      padding: 10px 16px;
      font-size: 14px;
      letter-spacing: 0.01em;
    }

    header {
      position: sticky;
      top: 0;
      backdrop-filter: blur(10px);
      background: rgba(255,255,255,.86);
      border-bottom: 1px solid rgba(230,233,242,.8);
      z-index: 40;
    }
    .nav {
      height: 76px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 16px;
    }
    .brand {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      font-weight: 700;
      font-size: 18px;
      letter-spacing: -0.02em;
    }
    .brand-mark {
      width: 32px; height: 32px; border-radius: 10px;
      background: linear-gradient(135deg, var(--accent), var(--accent-2));
      box-shadow: 0 8px 18px rgba(79,107,255,.35);
    }
    .nav-links { display: flex; gap: 22px; color: var(--muted); font-weight: 500; }
    .nav-actions { display: flex; align-items: center; gap: 12px; }

    .btn {
      display: inline-flex; align-items: center; justify-content: center;
      border: 1px solid transparent;
      border-radius: 999px;
      height: 44px;
      padding: 0 18px;
      font-weight: 600;
      transition: all .25s var(--ease);
      cursor: pointer;
      white-space: nowrap;
    }
    .btn-primary {
      background: linear-gradient(135deg, var(--accent), var(--accent-2));
      color: white;
      box-shadow: 0 8px 20px rgba(79,107,255,.28);
    }
    .btn-primary:hover { transform: translateY(-1px); box-shadow: 0 12px 26px rgba(79,107,255,.33); }
    .btn-ghost { border-color: var(--line); color: var(--text); background: var(--surface); }

    .hero { padding: 80px 0 70px; }
    .hero-inner { max-width: 840px; }
    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      border: 1px solid var(--line);
      background: #fff;
      border-radius: 999px;
      padding: 8px 14px;
      font-size: 13px;
      color: var(--muted);
      margin-bottom: 18px;
    }
    h1 {
      margin: 0;
      font-size: clamp(34px, 6vw, 62px);
      line-height: 1.05;
      letter-spacing: -0.03em;
      max-width: 14ch;
    }
    .hero p {
      margin: 18px 0 28px;
      font-size: clamp(17px, 2.2vw, 21px);
      color: var(--muted);
      max-width: 58ch;
    }
    .hero-actions { display: flex; gap: 12px; flex-wrap: wrap; }

    .trusted { padding: 22px 0 52px; }
    .trusted-label { color: var(--muted); font-size: 14px; margin-bottom: 16px; }
    .trusted-row {
      display: grid;
      grid-template-columns: repeat(6, minmax(0, 1fr));
      gap: 12px;
    }
    .logo {
      border: 1px solid var(--line);
      border-radius: 999px;
      height: 44px;
      display: flex; align-items: center; justify-content: center;
      background: #fff;
      color: #636a79;
      font-size: 13px;
      font-weight: 600;
    }

    .stats { padding: 20px 0 76px; }
    .stats-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 14px;
    }
    .stat {
      background: var(--surface);
      border: 1px solid var(--line);
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow);
      padding: 28px;
      min-height: 140px;
    }
    .stat-num {
      font-size: clamp(28px, 4.2vw, 46px);
      font-weight: 800;
      letter-spacing: -0.03em;
      line-height: 1;
      margin-bottom: 10px;
    }
    .stat-label { color: var(--muted); font-weight: 500; }

    section { scroll-margin-top: 96px; }
    .section-head { max-width: 680px; margin-bottom: 22px; }
    h2 { font-size: clamp(28px, 4vw, 44px); margin: 0 0 10px; letter-spacing: -0.02em; }
    .section-head p { margin: 0; color: var(--muted); }

    .search { padding: 40px 0 80px; }
    .search-shell {
      background: #fff;
      border: 1px solid var(--line);
      border-radius: 24px;
      box-shadow: var(--shadow);
      padding: 18px;
    }
    .tabs { display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 14px; }
    .tab {
      height: 40px; border-radius: 999px; padding: 0 14px;
      border: 1px solid var(--line); background: #fff; color: var(--muted);
      font-weight: 600; cursor: pointer; transition: all .22s var(--ease);
    }
    .tab[aria-selected="true"] {
      border-color: transparent;
      background: linear-gradient(135deg, rgba(79,107,255,.12), rgba(123,92,255,.14));
      color: #2432a7;
    }
    .filters { display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 16px; }
    .pill {
      height: 34px;
      border-radius: 999px;
      border: 1px solid var(--line);
      background: var(--surface-2);
      color: #5f6473;
      padding: 0 12px;
      font-size: 13px;
      font-weight: 600;
      cursor: pointer;
      transition: all .2s var(--ease);
    }
    .pill.active {
      background: #11131f;
      border-color: #11131f;
      color: #fff;
    }
    .results {
      display: grid;
      grid-template-columns: repeat(4, minmax(0, 1fr));
      gap: 12px;
      min-height: 220px;
    }
    .shot {
      aspect-ratio: 3/4;
      border-radius: var(--radius-md);
      border: 1px solid var(--line);
      background: linear-gradient(160deg, #f8f9ff, #f0f2fb);
      padding: 10px;
      position: relative;
      overflow: hidden;
      transition: transform .25s var(--ease), box-shadow .25s var(--ease);
    }
    .shot:hover { transform: translateY(-2px); box-shadow: 0 12px 22px rgba(17,24,39,.09); }
    .shot::before {
      content: "";
      position: absolute;
      inset: 12px;
      border-radius: 10px;
      background: linear-gradient(145deg, rgba(79,107,255,.14), rgba(123,92,255,.09));
      border: 1px solid rgba(79,107,255,.15);
    }
    .shot span {
      position: absolute;
      left: 18px;
      bottom: 16px;
      z-index: 2;
      font-weight: 600;
      color: #2f3552;
      font-size: 13px;
      background: rgba(255,255,255,.82);
      border: 1px solid rgba(223,227,238,.9);
      border-radius: 999px;
      padding: 4px 9px;
    }

    .flows { padding: 20px 0 80px; }
    .flow-shell {
      border: 1px solid var(--line);
      border-radius: 24px;
      background: #fff;
      box-shadow: var(--shadow);
      padding: 18px;
    }
    .mode-toggle { display: inline-flex; padding: 4px; border-radius: 999px; background: var(--surface-2); margin-bottom: 16px; }
    .mode-btn {
      border: none; background: transparent; color: #5d6474;
      padding: 10px 14px; border-radius: 999px; font-weight: 700; cursor: pointer;
      transition: all .25s var(--ease);
    }
    .mode-btn.active { background: #12131a; color: #fff; }
    .flow-view { display: none; }
    .flow-view.active { display: grid; }
    .video-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px; }
    .video-card, .proto-step {
      border: 1px solid var(--line);
      border-radius: var(--radius-md);
      background: linear-gradient(150deg, #f6f8ff, #ffffff);
      min-height: 170px;
      padding: 14px;
      position: relative;
    }
    .video-card::after {
      content: "▶";
      position: absolute;
      right: 14px; bottom: 10px;
      color: #3143c6;
      font-size: 20px;
      font-weight: 700;
    }
    .proto-grid { grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 12px; }

    .tools { padding: 10px 0 84px; }
    .tools-grid { display: grid; grid-template-columns: repeat(3, minmax(0,1fr)); gap: 14px; }
    .tool {
      border: 1px solid var(--line);
      border-radius: var(--radius-lg);
      background: #fff;
      box-shadow: var(--shadow);
      padding: 24px;
    }
    .icon {
      width: 40px; height: 40px; border-radius: 12px;
      background: linear-gradient(135deg, rgba(79,107,255,.15), rgba(123,92,255,.18));
      margin-bottom: 12px;
    }
    .tool h3 { margin: 0 0 8px; font-size: 20px; letter-spacing: -0.01em; }
    .tool p { margin: 0; color: var(--muted); }

    .testimonials { padding: 14px 0 90px; overflow: hidden; }
    .marquee-wrap { display: grid; gap: 12px; }
    .marquee {
      overflow: hidden;
      mask-image: linear-gradient(to right, transparent, black 8%, black 92%, transparent);
    }
    .track {
      display: flex;
      width: max-content;
      gap: 12px;
      animation: scrollX 40s linear infinite;
    }
    .track.reverse { animation-direction: reverse; animation-duration: 48s; }
    .quote {
      width: min(340px, 78vw);
      border: 1px solid var(--line);
      border-radius: 16px;
      background: #fff;
      box-shadow: var(--shadow);
      padding: 16px;
    }
    .quote p { margin: 0 0 12px; color: #2b3140; font-size: 15px; }
    .quote small { color: var(--muted); font-weight: 600; }

    .cta { padding: 10px 0 96px; }
    .cta-box {
      border-radius: 26px;
      background: radial-gradient(1200px 300px at 10% 0%, rgba(79,107,255,.16), transparent), #fff;
      border: 1px solid var(--line);
      box-shadow: var(--shadow);
      padding: 34px 20px;
      text-align: center;
      overflow: hidden;
    }
    .icon-marquee { margin: 24px 0 6px; overflow: hidden; }
    .icon-track {
      display: flex;
      gap: 10px;
      width: max-content;
      animation: scrollX 36s linear infinite;
    }
    .icon-track.reverse { animation-direction: reverse; animation-duration: 32s; }
    .app-icon {
      width: 48px; height: 48px; border-radius: 14px;
      border: 1px solid var(--line);
      background: linear-gradient(160deg, #fff, #eef1fd);
      display: grid; place-items: center;
      font-size: 12px; font-weight: 700; color: #58607a;
    }

    footer {
      border-top: 1px solid var(--line);
      padding: 22px 0 34px;
      color: var(--muted);
      font-size: 14px;
    }
    .footer-inner { display: flex; justify-content: space-between; gap: 12px; flex-wrap: wrap; }

    @keyframes scrollX {
      from { transform: translateX(0); }
      to { transform: translateX(-50%); }
    }

    @media (max-width: 980px) {
      .results { grid-template-columns: repeat(3, minmax(0,1fr)); }
      .video-grid { grid-template-columns: repeat(2, minmax(0,1fr)); }
      .proto-grid { grid-template-columns: repeat(2, minmax(0,1fr)); }
      .tools-grid { grid-template-columns: repeat(2, minmax(0,1fr)); }
      .trusted-row { grid-template-columns: repeat(3, minmax(0, 1fr)); }
    }
    @media (max-width: 760px) {
      .nav-links { display: none; }
      .stats-grid { grid-template-columns: 1fr; }
      .results { grid-template-columns: repeat(2, minmax(0,1fr)); }
      .tools-grid { grid-template-columns: 1fr; }
      .trusted-row { grid-template-columns: repeat(2, minmax(0, 1fr)); }
      .hero { padding-top: 56px; }
    }
    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after { animation: none !important; transition: none !important; }
    }
  </style>
</head>
