  <script>
    const featureTabs = ["Screens", "UI Elements", "Flows", "Text in Screenshot"];
    const filterCategories = ["Profile", "Wallet", "Welcome", "Account Setup", "Home", "Subscription & Paywall", "Login", "Settings", "Checkout", "Collections"];

    const dataset = {
      "Screens": {
        "Profile": ["Profile Header", "Account Card", "Usage Insights", "Privacy Settings"],
        "Wallet": ["Balance Summary", "Recent Transactions", "Add Card", "Transfer Flow"],
        "Welcome": ["Welcome Intro", "Benefit Highlights", "Account Prompt", "Theme Select"],
        "default": ["App Home", "Search View", "Dashboard", "Notification Center"]
      },
      "UI Elements": {
        "Profile": ["Avatar Stack", "Badge Pills", "Segment Control", "Preference Toggle"],
        "Wallet": ["Amount Input", "Currency Switch", "Security Badge", "Funding Selector"],
        "default": ["Tab Bars", "Cards", "Floating Actions", "Info Banners"]
      },
      "Flows": {
        "Checkout": ["Cart Review", "Shipping", "Payment", "Confirmation"],
        "Account Setup": ["Email Verify", "Profile Setup", "Preferences", "Done"],
        "default": ["Onboarding", "Upgrade", "Search to Save", "Share Collection"]
      },
      "Text in Screenshot": {
        "Subscription & Paywall": ["Try 7 Days", "Unlock Premium", "Upgrade Now", "Cancel Anytime"],
        "Login": ["Welcome Back", "Continue with Google", "Forgot Password", "Two-factor Code"],
        "default": ["Get Started", "Create Project", "Save Changes", "Invite Team"]
      }
    };

    const tabsEl = document.querySelector('.tabs');
    const filtersEl = document.querySelector('.filters');
    const resultsEl = document.querySelector('#results-grid');

    let activeTab = featureTabs[0];
    let activeFilter = filterCategories[0];

    function renderTabs() {
      tabsEl.innerHTML = '';
      featureTabs.forEach(tab => {
        const btn = document.createElement('button');
        btn.className = 'tab';
        btn.type = 'button';
        btn.role = 'tab';
        btn.setAttribute('aria-selected', String(tab === activeTab));
        btn.textContent = tab;
        btn.addEventListener('click', () => {
          activeTab = tab;
          renderTabs();
          renderResults();
        });
        tabsEl.appendChild(btn);
      });
    }

    function renderFilters() {
      filtersEl.innerHTML = '';
      filterCategories.forEach(filter => {
        const btn = document.createElement('button');
        btn.className = 'pill' + (filter === activeFilter ? ' active' : '');
        btn.type = 'button';
        btn.textContent = filter;
        btn.addEventListener('click', () => {
          activeFilter = filter;
          renderFilters();
          renderResults();
        });
        filtersEl.appendChild(btn);
      });
    }

    function renderResults() {
      resultsEl.innerHTML = '';
      const currentTabData = dataset[activeTab] || {};
      const items = currentTabData[activeFilter] || currentTabData.default || [];
      items.forEach((name) => {
        const card = document.createElement('article');
        card.className = 'shot';
        card.innerHTML = `<span>${name}</span>`;
        resultsEl.appendChild(card);
      });
    }

    renderTabs();
    renderFilters();
    renderResults();

    const modeButtons = document.querySelectorAll('.mode-btn');
    const videosView = document.getElementById('videos-view');
    const prototypeView = document.getElementById('prototype-view');

    ["Onboarding", "Checkout", "Paywall", "Referral", "Search", "Messaging"].forEach((v) => {
      const card = document.createElement('article');
      card.className = 'video-card';
      card.innerHTML = `<strong>${v} Flow Video</strong><p style="margin:8px 0 0;color:#61697a;">See how top apps sequence each step.</p>`;
      videosView.appendChild(card);
    });

    ["Step 1", "Step 2", "Step 3", "Step 4", "Step 5", "Step 6", "Step 7", "Step 8"].forEach((s, i) => {
      const card = document.createElement('article');
      card.className = 'proto-step';
      card.innerHTML = `<strong>${s}</strong><p style="margin:8px 0 0;color:#61697a;">Prototype interaction ${i + 1} with decision notes.</p>`;
      prototypeView.appendChild(card);
    });

    modeButtons.forEach((button) => {
      button.addEventListener('click', () => {
        modeButtons.forEach((btn) => btn.classList.remove('active'));
        button.classList.add('active');
        const mode = button.dataset.mode;
        videosView.classList.toggle('active', mode === 'videos');
        prototypeView.classList.toggle('active', mode === 'prototype');
      });
    });

    const counters = [...document.querySelectorAll('.stat-num')];
    let countersPlayed = false;
    const formatNumber = (n) => n.toLocaleString('en-US');

    function animateCount(element, target, delay = 0) {
      const start = performance.now() + delay;
      const duration = 1300;

      function tick(now) {
        if (now < start) {
          requestAnimationFrame(tick);
          return;
        }
        const progress = Math.min((now - start) / duration, 1);
        const eased = 1 - Math.pow(1 - progress, 3);
        element.textContent = formatNumber(Math.floor(target * eased));
        if (progress < 1) requestAnimationFrame(tick);
      }
      requestAnimationFrame(tick);
    }

    const statsObserver = new IntersectionObserver((entries) => {
      entries.forEach((entry, index) => {
