        card.innerHTML = `<span>${name}</span>`;
        resultsEl.appendChild(card);
      });
    }

    renderTabs();
    renderFilters();
    renderResults();

    const modeButtons = document.querySelectorAll('.mode-btn');
    const videosView = document.getElementById('videos-view');
    const prototypeView = document.getElementById('prototype-view');

    ["Onboarding", "Checkout", "Paywall", "Referral", "Search", "Messaging"].forEach((v) => {
      const card = document.createElement('article');
      card.className = 'video-card';
      card.innerHTML = `<strong>${v} Flow Video</strong><p style="margin:8px 0 0;color:#61697a;">See how top apps sequence each step.</p>`;
      videosView.appendChild(card);
    });

    ["Step 1", "Step 2", "Step 3", "Step 4", "Step 5", "Step 6", "Step 7", "Step 8"].forEach((s, i) => {
      const card = document.createElement('article');
      card.className = 'proto-step';
      card.innerHTML = `<strong>${s}</strong><p style="margin:8px 0 0;color:#61697a;">Prototype interaction ${i + 1} with decision notes.</p>`;
      prototypeView.appendChild(card);
    });

    modeButtons.forEach((button) => {
      button.addEventListener('click', () => {
        modeButtons.forEach((btn) => btn.classList.remove('active'));
        button.classList.add('active');
        const mode = button.dataset.mode;
        videosView.classList.toggle('active', mode === 'videos');
        prototypeView.classList.toggle('active', mode === 'prototype');
      });
    });

    const counters = [...document.querySelectorAll('.stat-num')];
    let countersPlayed = false;
    const formatNumber = (n) => n.toLocaleString('en-US');

    function animateCount(element, target, delay = 0) {
      const start = performance.now() + delay;
      const duration = 1300;

      function tick(now) {
        if (now < start) {
          requestAnimationFrame(tick);
          return;
        }
        const progress = Math.min((now - start) / duration, 1);
        const eased = 1 - Math.pow(1 - progress, 3);
        element.textContent = formatNumber(Math.floor(target * eased));
        if (progress < 1) requestAnimationFrame(tick);
      }
      requestAnimationFrame(tick);
    }

    const statsObserver = new IntersectionObserver((entries) => {
      entries.forEach((entry, index) => {
        if (entry.isIntersecting && !countersPlayed) {
          countersPlayed = true;
          counters.forEach((counter, idx) => animateCount(counter, Number(counter.dataset.target), idx * 130));
        }
      });
    }, { threshold: 0.45 });

    statsObserver.observe(document.querySelector('#stats'));

    const testimonials = [
      ["ScreenVault is my first stop before any redesign.", "Sebastian Speier — Product Design Lead"],
      ["The flow references are ridiculously useful for teams.", "Meng To — Design Founder"],
      ["Search by text-in-screen is a game-changer.", "Marco Cornacchia — Senior Product Designer"],
      ["Our team velocity improved after adopting ScreenVault.", "Daryl Ginn — UX Manager"],
      ["Best curation quality I’ve seen in inspiration tools.", "Rachel How — Product Designer"],
      ["From moodboard to implementation, it just fits.", "Haerin Song — Design Systems"],
    ];

    const marqueeContainer = document.getElementById('testimonial-marquees');
    [0, 1].forEach((row) => {
      const marquee = document.createElement('div');
      marquee.className = 'marquee';
      const track = document.createElement('div');
      track.className = 'track' + (row % 2 ? ' reverse' : '');

      const rowData = [...testimonials, ...testimonials];
      rowData.forEach(([quote, author]) => {
        const card = document.createElement('article');
        card.className = 'quote';
        card.innerHTML = `<p>“${quote}”</p><small>${author}</small>`;
        track.appendChild(card);
      });

      marquee.appendChild(track);
      marqueeContainer.appendChild(marquee);
    });

    const appBadges = ["Fin", "Soc", "Ed", "AI", "CRM", "Shop", "Pay", "Mail", "Fit", "Map", "Vid", "Cal"];
    function fillIconTrack(id) {
      const el = document.getElementById(id);
      [...appBadges, ...appBadges, ...appBadges].forEach((item) => {
        const icon = document.createElement('div');
        icon.className = 'app-icon';
        icon.textContent = item;
        el.appendChild(icon);
      });
    }
    fillIconTrack('icons-row-1');
    fillIconTrack('icons-row-2');
  </script>
